<script setup>
import {computed,ref,watch} from 'vue';
import {collectAlbumSongBatch,sortAlbumSongGroups} from '../shared/album-song-collector.mjs';
const props=defineProps({ request:Function, result:{type:Object,default:()=>({songs:[],playlists:[]})}, musicTab:{type:String,default:'search'}, searchType:{type:String,default:'songs'}, searchSort:{type:String,default:'default'}, selectedArtist:Object, selectedPlaylist:Object, playlists:{type:Array,default:()=>[]}, playlistSongLimit:{type:Number,default:50}, playlistCardLimit:{type:Number,default:40}, searchedQuery:{type:String,default:''}, offset:{type:Number,default:0}, local:Boolean, isBusy:Boolean, running:Boolean, permissions:{type:Array,default:()=>[]}, capabilities:{type:Object,default:()=>({})}, builder:Boolean, draftIds:{type:Array,default:()=>[]} });
const emit=defineEmits(['type','sort','artist','closeArtist','playlist','closePlaylist','moreSongs','morePlaylists','searchMore','control','draft']);
const resultViewport=ref(null);
const albumArtist=ref(null), albumList=ref([]), selectedAlbum=ref(null), albumBusy=ref(false), albumError=ref(''), albumOffset=ref(0), albumMore=ref(false);
const albumView=ref('songs'),albumGroups=ref([]),albumSongSort=ref('time'),albumProcessed=ref(0),collectionReady=ref(false);let collection=null;
const albumTrackCount=computed(()=>albumGroups.value.reduce((n,g)=>n+g.songs.length,0));
const moreAlbumSongs=computed(()=>albumArtist.value && albumTrackCount.value<500 && (!collectionReady.value || albumProcessed.value<albumList.value.length || albumMore.value));
const albumSongQuery=ref(''),expandedAlbums=ref(new Set());let beforeAlbumSearch=new Set();
const normalizeSearch=value=>String(value||'').normalize('NFKC').toLocaleLowerCase().trim();
function isAlbumOpen(key){return expandedAlbums.value.has(String(key));}
function albumToggle(key,event){if(event.target!==event.currentTarget)return;const next=new Set(expandedAlbums.value);if(event.currentTarget.open)next.add(String(key));else next.delete(String(key));expandedAlbums.value=next;}
function toggleAllAlbums(){expandedAlbums.value=allAlbumsExpanded.value?new Set():new Set(songSections.value.filter(s=>s.album).map(s=>String(s.key)));}
const allAlbumsExpanded=computed(()=>songSections.value.some(s=>s.album)&&songSections.value.filter(s=>s.album).every(s=>isAlbumOpen(s.key)));
const visibleAlbumSongs=computed(()=>songSections.value.reduce((n,s)=>n+s.songs.length,0));
let albumEpoch=0;
const working=computed(()=>props.isBusy || albumBusy.value);
function closeAlbums(){beforeAlbumSearch=new Set();expandedAlbums.value=new Set();albumSongQuery.value='';collection=null;collectionReady.value=false;albumGroups.value=[];albumProcessed.value=0;albumView.value='songs';albumSongSort.value='time';albumEpoch++;albumBusy.value=false;albumArtist.value=null;albumList.value=[];selectedAlbum.value=null;albumError.value='';albumMore.value=false;albumOffset.value=0;}
watch(()=>[props.result,props.searchedQuery,props.selectedPlaylist?.id,props.musicTab],closeAlbums);
async function openArtistAlbums(artist,more=false){
  if(working.value || !can('search') || !props.request)return;
  const epoch=++albumEpoch;const offset=more?albumOffset.value+30:0;
  if(!more){beforeAlbumSearch=new Set();expandedAlbums.value=new Set();albumSongQuery.value='';collection=null;collectionReady.value=false;albumGroups.value=[];albumProcessed.value=0;albumView.value='songs';albumSongSort.value='time';albumArtist.value={id:String(artist.id),name:artist.name};albumList.value=[];selectedAlbum.value=null;albumMore.value=false;}
  albumBusy.value=true;albumError.value='';
  try{const result=await props.request('music.artistAlbums',{id:String(artist.id),offset});if(epoch!==albumEpoch)return;if(String(result.artist?.id)!==String(artist.id))throw Error('返回的歌手与所选歌手不匹配');
    const combined=more?[...albumList.value,...result.albums]:result.albums;albumList.value=[...new Map(combined.map(a=>[a.id,a])).values()].slice(0,300);albumOffset.value=offset;albumMore.value=!!result.more;
    if(!collection)collection={albums:[...albumList.value],offset:albumOffset.value,more:albumMore.value,cursor:0,groups:[],trackCount:0};
    else Object.assign(collection,{albums:[...albumList.value],offset:albumOffset.value,more:albumMore.value});
    collectionReady.value=true;
    if(!more)await collectSongs(epoch);
  }catch(error){if(epoch===albumEpoch)albumError.value=error.message;}finally{if(epoch===albumEpoch)albumBusy.value=false;}
}
function syncCollection(){if(!collection)return;albumList.value=[...collection.albums];albumOffset.value=collection.offset;albumMore.value=collection.more;albumGroups.value=[...collection.groups];albumProcessed.value=collection.cursor;}
async function collectSongs(epoch){
  const current=collection;
  await collectAlbumSongBatch(current,{isCurrent:()=>epoch===albumEpoch,readAlbum:id=>props.request('music.album',{id}),readPage:async offset=>{const page=await props.request('music.artistAlbums',{id:albumArtist.value.id,offset});if(String(page.artist?.id)!==albumArtist.value?.id)throw Error('歌手专辑内容不匹配');return page;},onProgress:()=>{if(epoch===albumEpoch)syncCollection();}});
}
async function loadMoreAlbumSongs(){
  if(working.value)return;if(!collection)return openArtistAlbums(albumArtist.value);
  const epoch=++albumEpoch;albumBusy.value=true;albumError.value='';
  try{await collectSongs(epoch);}catch(error){if(epoch===albumEpoch)albumError.value=error.message;}finally{if(epoch===albumEpoch)albumBusy.value=false;}
}
async function openAlbum(album){
  if(working.value || !can('search'))return;const epoch=++albumEpoch;albumBusy.value=true;albumError.value='';
  try{const existing=collection?.groups.find(group=>String(group.album.id)===String(album.id)&&!group.truncated);const result=existing?{...existing.album,songs:existing.songs}:await props.request('music.album',{id:album.id});if(epoch!==albumEpoch)return;if(String(result.id)!==String(album.id))throw Error('专辑内容不匹配');selectedAlbum.value=result;}
  catch(error){if(epoch===albumEpoch)albumError.value=error.message;}finally{if(epoch===albumEpoch)albumBusy.value=false;}
}
function showAlbumList(){selectedAlbum.value=null;albumView.value='albums';albumError.value='';}
function searchAlbumArtist(){const artist=albumArtist.value;closeAlbums();emit('artist',{artist:{id:'',name:artist.name},order:'hot',more:false});}
function albumDate(value){return value?new Date(value).toISOString().slice(0,10):'';}
watch(()=>[props.searchedQuery,props.searchType,props.searchSort,props.selectedArtist?.artist.id,props.selectedArtist?.order,props.selectedPlaylist?.id],()=>{if(props.builder&&resultViewport.value)resultViewport.value.scrollTop=0;},{flush:'post'});
const can=permission=>props.local||props.permissions.includes(permission);
const state=computed(()=>({capabilities:props.capabilities}));
const shownSongs=computed(()=>selectedAlbum.value?selectedAlbum.value.songs:albumArtist.value?[]:props.selectedArtist?props.selectedArtist.songs:props.selectedPlaylist?props.selectedPlaylist.songs.slice(0,props.playlistSongLimit):props.searchSort==='popular'?[...props.result.songs].sort((a,b)=>(Number.isFinite(b.popularity)?b.popularity:-1)-(Number.isFinite(a.popularity)?a.popularity:-1)):props.result.songs);
const hasPopularity=computed(()=>props.result.songs.some(item=>Number.isFinite(item.popularity)));
const shownPlaylists=computed(()=>(props.musicTab==='playlists'?props.playlists:props.result.playlists).slice(0,props.playlistCardLimit));
function artistsFor(item){return item.artists?.length?item.artists:item.artist?[{id:'',name:item.artist}]:[];}
function formatTime(value){const seconds=Math.max(0,Math.floor(value||0));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');}
function artworkUrl(value){return typeof value==='string'?value.trim().replace(/^(?:http:)?\/\/((?:[a-z0-9-]+\.)*music\.126\.net)(?=[/:?#]|$)/i,'https://$1'):'';}
const allSongSections=computed(()=>selectedAlbum.value?[{key:'album-'+selectedAlbum.value.id,songs:selectedAlbum.value.songs}]:albumArtist.value?albumView.value==='songs'?sortAlbumSongGroups(albumGroups.value,albumSongSort.value).map(group=>({...group,key:group.album.id})):[]:(props.selectedArtist||props.selectedPlaylist||(props.musicTab==='search'&&props.searchType==='songs'&&props.result.songs.length))?[{key:'standard',songs:shownSongs.value}]:[]);
const songSections=computed(()=>{const query=albumArtist.value?normalizeSearch(albumSongQuery.value):'';return allSongSections.value.map(section=>({...section,totalSongs:section.songs.length,songs:query?section.songs.filter(song=>normalizeSearch([song.name,song.artist,song.album,section.album?.name].join(' ')).includes(query)):section.songs})).filter(section=>!query||section.songs.length);});
watch(albumSongQuery,(value,previous)=>{if(!albumArtist.value)return;if(normalizeSearch(value)){if(!normalizeSearch(previous))beforeAlbumSearch=new Set(expandedAlbums.value);expandedAlbums.value=new Set(songSections.value.filter(s=>s.album).map(s=>String(s.key)));}else expandedAlbums.value=new Set(beforeAlbumSearch);});
watch(albumGroups,()=>{if(normalizeSearch(albumSongQuery.value))expandedAlbums.value=new Set(songSections.value.filter(s=>s.album).map(s=>String(s.key)));});
function openArtist(artist,order='hot',more=false){if(props.capabilities.artistAlbums && props.request && artist.id)return openArtistAlbums(artist);emit('artist',{artist,order,more});}
function control(method,args){emit('control',{method,args});}
</script>

<template>
  <div class="music-search-results">
            <div v-if="musicTab === 'search' && !albumArtist && !selectedPlaylist && !selectedArtist && can('search')" class="search-result-tabs" role="group" aria-label="搜索结果类型">
              <button :class="{ active: searchType === 'songs' }" :aria-pressed="searchType === 'songs'" @click="emit('type','songs')">歌曲 <span>{{ result.songs.length }}</span></button>
              <button :class="{ active: searchType === 'playlists' }" :aria-pressed="searchType === 'playlists'" @click="emit('type','playlists')">相关歌单 <span>{{ result.playlists.length }}</span></button>
            </div>
            <div v-if="musicTab === 'search' && !albumArtist && !selectedPlaylist && !selectedArtist && searchType === 'songs' && result.songs.length" class="search-sort" role="group" aria-label="搜索歌曲排序"><span>排序</span><button :class="{ active: searchSort === 'default' }" @click="emit('sort','default')">综合</button><button :class="{ active: searchSort === 'popular' }" @click="emit('sort','popular')">人气优先</button><small v-if="searchSort === 'popular'">{{ hasPopularity ? '按已加载结果的接口热度排序，同热度保留综合顺序' : '此批结果未提供热度，保留综合顺序' }}</small></div>
            <template v-if="albumArtist">
              <button type="button" class="text-button" :disabled="working" @click="selectedAlbum ? showAlbumList() : closeAlbums()">{{ selectedAlbum ? '← 返回专辑列表' : '← 返回上一页' }}</button>
              <div v-if="!selectedAlbum" class="artist-heading"><div><span class="eyebrow">ARTIST ALBUMS</span><h2>{{ albumArtist.name }} · {{ albumView === 'songs' ? '歌曲' : '专辑' }}</h2><p>{{ albumView === 'songs' ? '已整理 ' + albumProcessed + ' 张专辑 · ' + albumTrackCount + ' 首曲目，按专辑分组' : '选择专辑查看歌曲' }}</p></div></div>
              <div v-else class="playlist-heading"><img v-if="selectedAlbum.coverUrl" :src="artworkUrl(selectedAlbum.coverUrl)" alt="专辑封面"><div><span class="eyebrow">ALBUM</span><h2>{{ selectedAlbum.name }}</h2><p>{{ selectedAlbum.artist }} · {{ selectedAlbum.songs.length }} 首歌曲</p></div></div>
              <div v-if="!selectedAlbum" class="search-result-tabs" role="group" aria-label="歌手曲目显示方式"><button :class="{active:albumView==='songs'}" :disabled="working" @click="albumView='songs'">专辑歌曲</button><button :class="{active:albumView==='albums'}" :disabled="working" @click="albumView='albums'">专辑列表</button></div>
              <div v-if="!selectedAlbum && albumView==='songs'" class="search-sort" role="group" aria-label="专辑歌曲排序"><button :class="{active:albumSongSort==='time'}" @click="albumSongSort='time'">按时间</button><button :class="{active:albumSongSort==='popular'}" @click="albumSongSort='popular'">按人气</button><small>{{ albumSongSort==='time' ? '按已加载专辑的发行日期排序，组内保留曲序' : '仅比较已加载歌曲的热度；专辑按组内最高热度排列，无热度保留原序' }}</small></div>
              <div v-if="selectedAlbum || albumView==='songs'" class="album-tools"><label class="album-song-search"><span aria-hidden="true">⌕</span><input v-model="albumSongQuery" type="search" aria-label="搜索专辑歌曲" placeholder="搜索已加载的歌曲、歌手或专辑"><button v-if="albumSongQuery" type="button" class="text-button" @click="albumSongQuery=''" aria-label="清空专辑歌曲搜索">清空</button></label><button v-if="!selectedAlbum && songSections.some(s=>s.album)" type="button" class="secondary album-expand-all" @click="toggleAllAlbums">{{ allAlbumsExpanded ? '全部收起' : '全部展开' }}</button></div><p v-if="albumSongQuery && (selectedAlbum || albumView==='songs')" class="album-search-count" role="status">找到 {{ visibleAlbumSongs }} 首歌曲，仅搜索已加载内容</p>
              <button type="button" class="text-button" :disabled="working" @click="searchAlbumArtist">搜索歌手名字</button>
              <p v-if="albumError" class="form-error" role="alert">{{ albumError }}</p>
              <p v-if="albumBusy" role="status">{{ albumView==='songs' && !selectedAlbum ? '正在整理专辑歌曲…' : '正在读取专辑…' }}</p>
            </template>
            <template v-if="selectedArtist && !albumArtist">
              <button class="text-button" @click="emit('closeArtist')">← 返回上一页</button><div class="artist-heading"><img v-if="selectedArtist.artist.coverUrl" :src="artworkUrl(selectedArtist.artist.coverUrl)" alt="歌手封面"><div><span class="eyebrow">ARTIST</span><h2>{{ selectedArtist.artist.name }}</h2><p v-if="selectedArtist.artist.description">{{ selectedArtist.artist.description }}</p></div></div>
              <div class="search-result-tabs" role="group" aria-label="歌手歌曲排序"><button :class="{ active: selectedArtist.order === 'hot' }" :disabled="working" @click="openArtist(selectedArtist.artist, 'hot')">热门歌曲</button><button :class="{ active: selectedArtist.order === 'time' }" :disabled="working" @click="openArtist(selectedArtist.artist, 'time')">最新歌曲</button></div>
            </template>
            <template v-if="selectedPlaylist && !selectedArtist && !albumArtist">
              <button class="text-button" @click="emit('closePlaylist')">← 返回列表</button><div class="playlist-heading"><img v-if="selectedPlaylist.coverUrl" :src="artworkUrl(selectedPlaylist.coverUrl)" alt="歌单封面"><div v-else class="playlist-placeholder" aria-hidden="true">♫</div><div><span class="eyebrow">PLAYLIST</span><h2>{{ selectedPlaylist.name }}</h2><p>{{ selectedPlaylist.songs.length }} 首歌曲 · 最多载入 500 首</p><p v-if="selectedPlaylist.openedBy">{{ selectedPlaylist.openedBy }} 开放</p><p v-if="selectedPlaylist.source === 'local' && selectedPlaylist.description" class="playlist-description" aria-label="歌单简介">{{ selectedPlaylist.description }}</p><p v-if="!local && selectedPlaylist.publicPreview && !selectedPlaylist.published">整单播放前，请先加入开放歌单。</p><div class="inline-actions"><slot name="playlist-actions"/></div></div></div>
            </template>
            <div ref="resultViewport" class="search-result-items" :class="{'bounded-search-results':builder}" :role="builder ? 'region' : undefined" :aria-label="builder ? '自建歌单搜索结果' : undefined" :tabindex="builder ? 0 : undefined"><template v-if="albumArtist && !selectedAlbum && albumView==='albums'"><div class="playlist-grid artist-album-grid"><article class="playlist-card-entry" v-for="album in albumList" :key="album.id"><button type="button" class="playlist-card" :disabled="working" @click="openAlbum(album)"><img v-if="album.coverUrl" :src="artworkUrl(album.coverUrl)" loading="lazy" decoding="async" alt=""><div v-else class="playlist-cover-placeholder" aria-hidden="true">♫</div><strong>{{ album.name }}</strong><span>{{ album.songCount }} 首 · {{ albumDate(album.publishTime) }}</span><small>{{ album.artist }}</small></button></article></div><div v-if="!albumBusy && !albumList.length && !albumError" class="empty-state">暂无可显示的专辑</div><button v-if="albumError && !albumList.length" type="button" class="secondary" :disabled="working" @click="openArtistAlbums(albumArtist)">重新读取专辑</button><button v-if="albumMore" type="button" class="secondary load-more" :disabled="working" @click="openArtistAlbums(albumArtist,true)">加载更多专辑</button></template><div v-if="selectedAlbum && !selectedAlbum.songs.length" class="empty-state">专辑暂无可显示的歌曲</div><component :is="section.album ? 'details' : 'section'" v-for="section in songSections" :key="section.key" :class="{'album-song-section':section.album}" :open="section.album ? isAlbumOpen(section.key) : undefined" @toggle="section.album && albumToggle(section.key,$event)"><summary v-if="section.album" class="album-song-heading" :aria-label="'专辑 ' + section.album.name"><img v-if="section.album.coverUrl" :src="artworkUrl(section.album.coverUrl)" loading="lazy" decoding="async" alt=""><div><h3>{{ section.album.name }}</h3><p>{{ albumDate(section.album.publishTime) }} · {{ albumSongQuery ? section.songs.length + ' / ' + section.totalSongs : section.songs.length }} 首<span v-if="section.truncated">（达到载入上限）</span></p></div><svg class="album-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7"/></svg></summary><div class="song-list"><div v-if="!section.album && !selectedAlbum" class="song-row table-head" :class="{'with-draft':state.capabilities?.community && can('savePlaylist')}"><span>#</span><span>歌曲</span><span>专辑</span><span>时长</span><span></span></div><div class="song-row" :class="{'with-draft':state.capabilities?.community && can('savePlaylist'),'album-track-row':section.album || selectedAlbum}" v-for="(item, i) in section.songs" :key="item.id + '-' + i"><span v-if="!section.album && !selectedAlbum" class="song-number">{{ String(i + 1).padStart(2, '0') }}</span><div class="song-title"><img v-if="item.coverUrl" :src="artworkUrl(item.coverUrl)" loading="lazy" decoding="async" alt=""><div><strong>{{ item.name }} <small class="vip" v-if="item.vip">VIP</small></strong><small class="song-artists"><template v-for="(artist, ai) in artistsFor(item)" :key="artist.id || artist.name"><span v-if="ai"> / </span><button v-if="can('search')" class="artist-link" :disabled="working" :title="(capabilities.artistAlbums ? '查看歌手歌曲 ' : capabilities.artistNameSearch ? '搜索歌手 ' : '查看歌手 ') + artist.name" @click="openArtist(artist)">{{ artist.name }}</button><span v-else>{{ artist.name }}</span></template></small></div></div><span v-if="!section.album && !selectedAlbum" class="album">{{ item.album }}</span><span class="song-duration">{{ formatTime(item.duration) }}</span><div class="song-actions"><span class="song-queue-actions"><button :title="state.capabilities?.queueInterruption ? '立即插播，当前歌曲排到下一首并从头播放' : '先备份队列并重开工具，才能使用保留队列的插播'" @click="control('music.playNow', { id: item.id })" :disabled="!running || working || !can('playNow') || !state.capabilities?.queueInterruption" v-if="can('playNow')">▶</button><button title="加入队列" @click="control('music.add', { id: item.id })" :disabled="!running || working || !can('add')">+</button></span><span v-if="state.capabilities?.community && can('savePlaylist')" class="song-save-action"><button type="button" class="playlist-save-trigger" :class="{saved:draftIds.includes(item.id)}" :title="draftIds.includes(item.id) ? '当前草稿已加入，可选择其他歌单' : '加入歌单'" :aria-label="'加入歌单 ' + item.name" aria-haspopup="dialog" @click="emit('draft',item)" :disabled="working"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 5h14M4 10h10M4 15h6"/><path v-if="draftIds.includes(item.id)" d="m13 17 3 3 6-7"/><path v-else d="M18 13v8m-4-4h8"/></svg></button></span></div></div></div></component>
            <p v-if="albumSongQuery && !visibleAlbumSongs && (selectedAlbum || albumView==='songs')" class="album-search-empty">已加载歌曲中没有匹配结果<span v-if="moreAlbumSongs">，可加载更多歌曲后继续筛选</span></p>
            <template v-if="albumArtist && !selectedAlbum && albumView==='songs'"><button v-if="moreAlbumSongs" type="button" class="secondary load-more" :disabled="working" @click="loadMoreAlbumSongs">{{ albumError ? '重试加载歌曲' : '加载更多歌曲' }}</button><p v-if="albumTrackCount>=500" class="album-limit-hint">已载入 500 首曲目</p><div v-if="!albumBusy && !albumTrackCount && !albumError" class="empty-state">暂无可整理的专辑歌曲</div></template>
            <button v-if="!albumArtist && selectedPlaylist && playlistSongLimit < selectedPlaylist.songs.length" class="secondary load-more" @click="emit('moreSongs')">显示更多歌曲（{{ shownSongs.length }} / {{ selectedPlaylist.songs.length }}）</button>
            <button v-if="!albumArtist && selectedArtist?.more" class="secondary load-more" @click="openArtist(selectedArtist.artist, selectedArtist.order, true)" :disabled="working">加载更多歌手歌曲</button>
            <div class="empty-state" v-if="!albumArtist && selectedArtist && !selectedArtist.songs.length">暂时没有可显示的歌手歌曲</div>
            <div class="playlist-grid" v-if="!albumArtist && !selectedPlaylist && !selectedArtist && (musicTab === 'playlists' || (musicTab === 'search' && searchType === 'playlists'))">
              <article class="playlist-card-entry" v-for="item in shownPlaylists" :key="item.id">
                <button class="playlist-card" @click="emit('playlist',item)" :disabled="working"><img v-if="item.coverUrl" :src="artworkUrl(item.coverUrl)" loading="lazy" decoding="async" alt=""><div v-else class="playlist-cover-placeholder" aria-hidden="true">♫</div><strong>{{ item.name }}</strong><span>{{ item.songCount || 0 }} 首 · {{ item.source === 'local' ? '本地保存' : '网易云音乐' }}</span><small v-if="item.openedBy">{{ item.openedBy }} 开放</small></button>
                <slot name="playlist-card-actions" :item="item"/>
              </article>
            </div>
            <button v-if="!albumArtist && !selectedPlaylist && !selectedArtist && (musicTab === 'playlists' || (musicTab === 'search' && searchType === 'playlists')) && shownPlaylists.length < (musicTab === 'playlists' ? playlists : result.playlists).length" class="secondary load-more" @click="emit('morePlaylists')">显示更多歌单</button>
            <button v-if="musicTab === 'search' && !albumArtist && !selectedPlaylist && !selectedArtist && result[searchType].length && offset < 600" class="secondary load-more" @click="emit('searchMore')" :disabled="working">加载更多{{ searchType === 'playlists' ? '歌单' : '歌曲' }}</button>
            <div class="empty-state" v-if="!albumArtist && !selectedPlaylist && !selectedArtist && musicTab !== 'community' && (musicTab === 'search' ? !result[searchType].length : !playlists.length)"><slot name="empty"><div>♫</div><h3>{{ searchedQuery ? searchType === 'songs' ? '没有找到相关歌曲' : '没有找到相关歌单' : '下一首，从这里开始' }}</h3><p>{{ searchedQuery ? '换个关键词试试，或切换搜索结果类型' : '输入歌名、歌手或歌单名称开始搜索' }}</p></slot></div>
            </div>
  </div>
